    bg_counts = collections.Counter()
    for r in range(H):
        for c in range(W):
            bg_counts[grid[r][c]] += 1
        bg = bg_counts.most_common(1)[0][0]

    def find_objects(exclude_row, exclude_col):
        visited = set()
        objects = []
        for r in range(H):
            for c in range(W):
                if (r, c) in visited or grid[r][c] == bg:
                    continue
                if exclude_row and r == exclude_row:
                    continue
                if exclude_col and c == exclude_col:
                    continue

                # BFS to find connected component
                cells = [(r, c)]
                min_r, max_r, min_c, max_c = r, r, c, c
                visited.add((r, c))
                stack = [(r, c)]

                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if (nr == exclude_row) and exclude_col: continue
                            if (nc == exclude_col) and exclude_row: continue
                            if grid[nr][nc] != bg and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                                cells.append((nr, nc))
                                min_r = min(min_r, nr)
                                max_r = max(max_r, nr)
                                min_c = min(min_c, nc)
                                max_c = max(max_c, nc)

                objects.append({
                    'cells': cells,
                    'min_r': min_r,
                    'max_r': max_r,
                    'min_c': min_c,
                    'max_c': max_c
                })
        return objects

    def apply_legend(objects, legend_coords, is_col):
